CREATE SCHEMA IF NOT EXISTS `aidirac-503309.careers` OPTIONS(location="asia-south1");
CREATE TABLE IF NOT EXISTS `aidirac-503309.careers.applications` (application_id STRING, submitted_at TIMESTAMP, status STRING, full_name STRING, email STRING, whatsapp STRING, country_of_residence STRING, nationality STRING, passport_valid BOOL, passport_expiry DATE, willing_to_travel BOOL, preferred_postings ARRAY<STRING>, role STRING, experience_years INT64, highest_education STRING, certifications ARRAY<STRUCT<provider STRING,name STRING,credential_id STRING,verify_url STRING,expiry DATE>>, prism_ai_ready BOOL, prism_ai_experience STRING, motivation STRING, sample_url STRING, cv_gcs_uri STRING, cv_original_filename STRING, cv_mime STRING, cv_size_bytes INT64, consent_dpdp BOOL, consent_contact BOOL, source STRING, utm JSON, ip_hash STRING, reviewer_notes STRING, updated_at TIMESTAMP) PARTITION BY DATE(submitted_at) CLUSTER BY role,status;
ALTER TABLE `aidirac-503309.careers.applications` ADD COLUMN IF NOT EXISTS reviewer_notes STRING;
CREATE TABLE IF NOT EXISTS `aidirac-503309.careers.application_events` (application_id STRING, at TIMESTAMP, event STRING, actor STRING, detail JSON);
